# Calutmar sculpted from nothing on the skeleton and clips of the game's own export of it (sculptkit.py):
#   blender --background --factory-startup --python sculpts/calutmar.py -- <the export's Calutmar.glb> <out.glb>
#
# Carpathia No. 10131, the Little Steed Pokemon (plan 46, CP-dex-3, "131. Calutmar: a seahorse"); the game has no
# sculptor of it, so its export is a fish generated by rule: only its skeleton, its clips and its size are taken.
# From the picture: a sandy yellow seahorse standing upright; a round head with a long tube of a snout, open at its
# flared end in a dark round hole; large eyes with a blue iris, a dark pupil and a glint, under a brow that cuts their
# top on a slope down toward the snout (brave); a great fan of orange fin with dark teal spines poking past it, from
# the top of the head down the back of the neck (the brief's "frill of fins like a little mane"); a plump belly paler
# than the back, crossed by grooves; a smaller orange fan with teal spines on the back, and a pale see-through
# pectoral fin before it; the tail curled forward under the body in a thick coil.
#
# The skeleton is a level fish's (head joint low in front at z 0.2, tail and fins swinging from the middle): an
# upright seahorse on it would have its head swung from 0.65 below and its coil swung by the tail's 46 degrees, so
# every part is on `body` (rules for a seahorse on a fish's skeleton). Built to the export's longest side (its length,
# 1.11) as the seahorse's height, hovering from the export's lowest (0.044).
#
# Written to be grown from (calutregal.py imports it with sibling): the coil, the fans of fin with spines, the belly's
# grooves and the eye are functions; the build is under the main guard.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import Kit, ell, tube, srgb, inside, unit, eye_look, args, outward, slab, polygon

SAND, BELLY, GROOVE = "#E4AC50", "#F5D68C", "#BF8638"
FIN, SPINE, PECT = "#EE7C3A", "#2A7880", "#F4EAC4"
HOLE, IRIS, INK, WHITE, PUPIL = "#3A2014", "#4A9EC0", "#2A1C16", "#FAFAF6", "#120E14"

# ---- the picture's frame: a pixel of the 1024 picture is S_ units; its x is the model's -y (the snout at the left) --
S_, Z0, PX0, PY0 = 0.0013, 0.088, 500, 915


def at(px, py, x=0.0, s=S_):
    return np.array([x, (px - PX0) * s, Z0 + (PY0 - py) * s])


HEAD_C, HEAD_R = at(478, 318), np.array([0.104, 0.112, 0.102])
EYE_N = unit(0.68, -0.7, 0.2)
EYE_HALF = (0.043, 0.047)
BACK_TURN = 25.0          # fans and coil turned this far about the upright toward +X at the back


def turned(deg):
    """The back direction turned deg degrees toward +X (the game's front camera sees the +X three-quarter)."""
    t = math.radians(deg)
    return np.array([math.sin(t), math.cos(t), 0.0])


def coil(k, centre, a0, turns, r0, r1, t0, t1, turn, start=None, color=SAND, bone="body", name="tail"):
    """The tail: down the back, round under and up the front, curling in, in the midline plane turned toward +X."""
    n = 44
    s = np.linspace(0, 1, n)
    th = np.radians(a0 - s * 360 * turns)
    rr = r0 + (r1 - r0) * s ** 0.85
    back = turned(turn)
    P = [centre + back * (rr[i] * math.cos(th[i])) + np.array([0, 0, rr[i] * math.sin(th[i])]) for i in range(n)]
    R = t0 + (t1 - t0) * s ** 1.05
    if start is not None:
        P = [np.array(p) for p in start] + P
        R = np.concatenate([[t0 * 1.1] * len(start), R])
    k.add(name, tube(P, R, seg=20, per=4), color, bone)
    return P, R


def fan(k, name, origin, ex, tips, inner, hub, membrane=FIN, spine=SPINE, thick=0.03, spine_r=0.019, notch=0.87,
        bone="body", spines=True, ez=(0, 0, 1.0)):
    """A fan of fin: a membrane (a plate with notches between its points) and a solid spine along each point that
    pokes a little past it. tips and inner are (a, b) in the plane of ex (back) and ez (up) through origin, the tips
    in order round the fan, inner the edge back from the last tip to the first, inside the body."""
    ex = np.array(ex, float); ez = np.array(ez, float)
    hub = np.array(hub, float)
    T = [np.array(t, float) for t in tips]
    out = []
    for i, t in enumerate(T):
        out.append(t)
        if i + 1 < len(T):
            out.append(hub + notch * ((t + T[i + 1]) / 2 - hub))
    out += [np.array(p, float) for p in inner]
    k.add(name, slab([tuple(p) for p in out], origin, ex, ez, thick), membrane, bone, fuse=False, surface="shell")
    if not spines:
        return
    w = lambda p: np.array(origin) + p[0] * ex + p[1] * ez
    for i, t in enumerate(T):
        a, b = hub + 0.28 * (t - hub), hub + 1.035 * (t - hub)
        m = (a + b) / 2
        k.add(f"{name}spine{i}", outward(tube([w(a), w(m), w(b)], [spine_r, spine_r * 0.95, spine_r * 0.88], seg=12,
                                               per=4)), spine, bone, fuse=False, surface="shell")


def grooves(k, rows, front_y, color=GROOVE, half_h=0.006, n=(0.0, -1.0, 0.0)):
    """Crisp grooves across the belly: (z, half width) each, thin lens patches cast from the front."""
    for z, w in rows:
        k.decal((0.0, front_y, z), unit(*n), (w, half_h), color, eps=0.0035, rings=4, segs=36)


# ---- the eye: big, a blue iris, a dark pupil and a glint, its top cut by a brow sloping down to the snout ---------
def make_eye(white=WHITE, iris=IRIS, ink=INK, pupil=PUPIL, top=lambda u: 0.36 + 0.34 * u, iris_r=0.62,
             lash=None):
    CW, CI, CK, CP = srgb(white), srgb(iris), srgb(ink), srgb(pupil)

    def eye(u, v):
        # +u runs toward the back on both sides of a sideways patch
        c = np.tile(CK, (len(u), 1))
        rr = u * u + v * v
        wh = (rr < 0.74) & (v < top(u) - 0.16)
        c[wh] = CW
        ir = wh & (((u + 0.12) / iris_r) ** 2 + ((v + 0.06) / (iris_r * 1.12)) ** 2 < 1)
        c[ir] = CI
        c[wh & (((u + 0.14) / (iris_r * 0.5)) ** 2 + ((v + 0.08) / (iris_r * 0.6)) ** 2 < 1)] = CP
        c[wh & (((u + 0.0) / 0.15) ** 2 + ((v - 0.2) / 0.16) ** 2 < 1)] = CW
        if lash is not None:
            c[lash(u, v)] = CK
        return c
    return eye


def eye_outline(top, bot=-0.9, n=96):
    t = np.linspace(0, 2 * math.pi, n, endpoint=False)
    u, v = 0.98 * np.cos(t), 0.98 * np.sin(t)
    v = np.minimum(np.clip(v, bot, None), top(u))
    return np.stack([u, v], axis=1)


def lay_eyes(k, centre, normal, half, eye, lid, ink=INK, top=lambda u: 0.36 + 0.34 * u, line=0.17):
    OUT = eye_outline(top)
    M = np.array([-1.0, 1, 1])
    centre, normal = np.array(centre), np.array(normal)

    def lay(state):
        look = eye if state == "Open" else eye_look(state, eye, srgb(lid), srgb(ink), line=line)
        # laid by hand a side, since a mirrored patch's outline is not mirrored
        k.decal(centre, normal, half, look, eps=0.0035, rings=20, segs=56, outline=polygon(OUT))
        k.decal(centre * M, normal * M, half, lambda u, v, look=look: look(-u, v), eps=0.0035, rings=20, segs=56,
                outline=polygon(OUT * np.array([-1, 1])))
    return lay


# ---- Calutmar -------------------------------------------------------------------------------------------------------
def head(k):
    k.add("head", ell(HEAD_C, HEAD_R), SAND, "body")
    k.add("jowl", ell(at(486, 372), (0.078, 0.082, 0.066)), SAND, "body")
    k.add("cheek", ell(HEAD_C + EYE_N * HEAD_R * 0.66, (0.056, 0.05, 0.058),
                       rot=(0, 0, -math.degrees(math.atan2(EYE_N[0], -EYE_N[1])))), SAND, "body", mirror=True)
    # the snout: a tube forward and a little down, flared at its end round a dark hole
    k.add("snout", tube([at(445, 358), at(388, 382), at(332, 394)], [0.048, 0.034, 0.029]), SAND, "body")
    tip = at(310, 401)
    k.add("snouttip", ell(tip, (0.036, 0.022, 0.036)), SAND, "body")
    k.decal(tip + (0, -0.022, 0), unit(0, -1, -0.08), (0.02, 0.021), HOLE, eps=0.003, rings=10, segs=40)


def body(k):
    k.add("neck", tube([at(502, 392), at(494, 440), at(480, 492)], [0.076, 0.082, 0.096]), SAND, "body")
    k.add("belly", ell(at(468, 578), (0.128, 0.12, 0.16)), SAND, "body")
    k.add("back", tube([at(528, 410), at(548, 500), at(553, 600), at(548, 690)], [0.05, 0.058, 0.062, 0.058]),
          SAND, "body")
    k.add("lower", tube([at(472, 640), at(498, 700), at(545, 752), at(592, 788)], [0.108, 0.094, 0.078, 0.064]),
          SAND, "body")
    coil(k, centre=at(497, 822), a0=22.0, turns=1.38, r0=0.15, r1=0.028, t0=0.058, t1=0.019, turn=BACK_TURN)
    # the paler belly down the front, and its grooves
    def front(P):
        return (inside(P[:, 1] - 0.01, 0.004) * inside(0.34 - P[:, 2], 0.005) * inside(P[:, 2] - 0.74, 0.005))
    k.paint(front, BELLY, on=["belly", "neck", "lower"])
    rows = []
    for py in (468, 515, 562, 610, 655, 698):
        z = at(0, py)[2]
        w = 0.085 * (1 - 0.55 * ((z - 0.52) / 0.22) ** 2)
        rows.append((z, max(w, 0.045)))
    grooves(k, rows, -0.1)
    # the plates carried round the back: grooves across the back's ridge, cast from behind
    for py in (440, 490, 540, 590, 640, 690):
        k.decal(at(548, py) + (0, 0.02, 0), (0, 1.0, 0), (0.05, 0.006), GROOVE, eps=0.0035, rings=4, segs=36)


def fins(k):
    # the great fan from the top of the head down the back of the neck: in the head's plane turned toward +X
    ex = turned(BACK_TURN)
    s = S_
    rel = lambda px, py: ((px - 478) * s, (318 - py) * s)
    tips = [rel(408, 158), rel(487, 95), rel(582, 102), rel(655, 160), rel(690, 270), rel(678, 378), rel(630, 438)]
    inner = [rel(560, 470), rel(520, 360), rel(470, 300), rel(430, 270)]
    fan(k, "crest", HEAD_C, ex, tips, inner, hub=rel(500, 300), thick=0.03, spine_r=0.019)
    # the smaller fan on the back, and the pale pectoral fin before it
    o = at(548, 562)
    rel2 = lambda px, py: ((px - 548) * s, (562 - py) * s)
    tips2 = [rel2(626, 478), rel2(650, 520), rel2(660, 570), rel2(646, 614), rel2(618, 650)]
    inner2 = [rel2(560, 640), rel2(555, 490)]
    fan(k, "backfin", o, turned(35.0), tips2, inner2, hub=rel2(565, 565), thick=0.028, spine_r=0.017)
    pectoral(k, at(515, 565, 0.075), 0.11)


def pectoral(k, o, L, color=PECT, rib=GROOVE, name="pect"):
    """A pale fan of a pectoral fin on each side, out and back, its face to the front cameras, a few ribs."""
    ex, ez = unit(0.66, 0.75, 0.0), np.array([0, 0, 1.0])
    pts = [(0.0, -0.02)]
    for i in range(9):
        a = math.radians(-55 + 110 * i / 8)
        r = L * (1.0 if i % 2 == 0 else 0.86)
        pts.append((r * math.cos(a), r * math.sin(a)))
    pts.append((0.0, 0.02))
    k.add(name, slab(pts, o, ex, ez, 0.018), color, "body", fuse=False, mirror=True, surface="shell")
    n = np.cross(ex, ez)
    for i in range(5):
        a = math.radians(-55 + 110 * i / 4)
        d = ex * math.cos(a) + ez * math.sin(a)
        p0, p1 = o + d * L * 0.12 + n * 0.006, o + d * L * 0.9 + n * 0.006
        k.add(f"{name}rib{i}", outward(tube([p0, (p0 + p1) / 2, p1], [0.009, 0.0085, 0.008], seg=8, per=3)), rib,
              "body", fuse=False, mirror=True, surface="shell")


def calutmar(src, out):
    k = Kit(src, coat="scales")
    head(k)
    body(k)
    fins(k)
    k.build(voxel=0.0062, smooth=3, band=0.006)
    k.eye_states(lay_eyes(k, HEAD_C + EYE_N * HEAD_R * 1.02, EYE_N, EYE_HALF, make_eye(), SAND))
    k.export(out)


if __name__ == "__main__":
    calutmar(*args())
